class Solution:
    MOD = 10**9 + 7

    def __init__(self, s):
        self.s = s
        self.pos = 0

    def parse(self):
        return self.parse_expression()

    def parse_expression(self):
        # <expression> ::= <term> | <expression> '+' <term>
        result = self.parse_term()

        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1  # skip '+'
            term = self.parse_term()
            result = self.concat_nums(result, term)

        return result

    def parse_term(self):
        # <term> ::= <number> | <number> '-' <number> | <number> '(' <expression> ')'
        start = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1
        l = int(self.s[start:self.pos])

        if self.pos < len(self.s) and self.s[self.pos] == '-':
            self.pos += 1  # skip '-'
            start = self.pos
            while self.pos < len(self.s) and self.s[self.pos].isdigit():
                self.pos += 1
            r = int(self.s[start:self.pos])
            return self.range_concat(l, r)
        elif self.pos < len(self.s) and self.s[self.pos] == '(':
            self.pos += 1  # skip '('
            expr = self.parse_expression()
            if self.pos < len(self.s) and self.s[self.pos] == ')':
                self.pos += 1  # skip ')'
                return self.repeat_concat(l, expr)
            else:
                raise ValueError("Expected ')', found other")
        else:
            return str(l)

    def parse_number(self):
        start = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1
        return int(self.s[start:self.pos])

    def get_num_digits(self, n):
        s = str(n)
        return len(s)

    def concat_nums(self, a, b):
        """Concatenate two number strings a followed by b, modulo MOD"""
        return (int(a) * pow(10, len(b), self.MOD) + int(b)) % self.MOD

    def range_concat(self, l, r):
        """
        Concatenate numbers from l to r, modulo MOD.
        Returns list of digit strings or None for very large ranges.
        """
        result = ""
        if r - l + 1 <= 100000:
            for i in range(l, r + 1):
                result += str(i)
        else:
            raise ValueError("Range too large")
        return result % self.MOD

    def repeat_concat(self, n, expr):
        """Repeat expr string n times and concatenate, modulo MOD"""
        s_expr = str(expr)
        if len(s_expr) == 0:
            return "0"

        # Efficiently compute n repetitions concatenated as string
        s_expr_len = len(s_expr)
        n_str = str(n)

        # Create the full concatenated string efficiently
        full = n_expr_to_concat(s_expr_len, n)

        # Convert to int modulo MOD
        return int(full) % self.MOD


