    def dist(p1, p2):
        return ((p1[0] - p2[0])**2 + **(p1[1] - p2[1])2)**0.5

    def circumradius(p1, p2, p3):
        d1 = dist(p1, p2)
        d2 = dist(p2, p3)
        d3 = dist(p3, p1)

        # Check for valid triangle (triangle inequality with positive area)
        if d1 + d2 <= d3 or d2 + d3 <= d1 or d3 + d1 <= d2:
            return 0

        # Compute area using cross product
        area = 0.5 * abs(p1[0] * (p2[1] - p3[1]) + 
                        p2[0] * (p3[1] - p1[1]) + 
                        p3[0] * (p1[1] - p2[1]))

        if area < 1e-9:
            return 0

        return (d1 * d2 * d3) / (4 * area)

    max_radius = -1
    found_valid = False

    # Check all triples
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                r = circumradius(centers[i], centers[j], centers[k])
                if r > 0:
                    found_valid = True
                    if r > max_radius:
                        max_radius = r

    if not found_valid:
        return "-1\n"

    return f"{max_radius:.8f}\n"

