    # Find three internally vertex-disjoint paths
    # Pattern: start connects to many nodes, end connects to the same nodes
    # If start and end share at least 3 common neighbors (excluding each other),
    # we can form 3 paths through each common neighbor

    for start in range(1, n + 1):
        if len(adj[start]) < 3:
