            neighbor_set_end = set(adj[end])
            common = neighbor_set_start.intersection(neighbor_set_end)
            common.discard(start)
            common.discard(end)

            if len(common) >= 3:
                # Found enough common neighbors to form 3 paths
                path_edges = []
                count = 0

                for mid in list(common):
                    if count >= 3:
                        break

                    # mid is a common neighbor, so it's connected to both start and end
                    path_edges.append((start, mid, end))
                    count += 1

                if len(path_edges) >= 3:
                    result = ["YES"]
                    for s, mid, t in path_edges[:3]:
