def is_uniform_rectangles(matrix, n, m, r, c):
    """
    Check if all r×c non-overlapping rectangles are pairwise equal.
    """
    # Each rectangle at position (i,j) covers matrix[i:i+r][j:j+c]
    # All rectangles must be identical

    # Sample first rectangle and compare all others against it
    sample = []
    for i in range(r):
        for j in range(c):
            sample.append(matrix[i][j])

    # Check all other rectangles match
    for i in range(r, n, r):
