    step = max_val // n  # Approximately equal intervals
    remainder = max_val % n  # Distribute remainder to first few intervals

    result = ["!"]
    current = 0

    for i in range(n):
        end = current + step + (1 if i < remainder else 0)
        result.append(f"{current} {end}")
        current = end

    return "\n".join(result) + "\n"

